const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Split raw input into trimmed, non-comment, whitespace-tokenised lines,
 * paired with their 1-based line number.
 */
function tokenizeLines(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const lines = []
  for (let i = 0; i < rawLines.length; i++) {
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    lines.push({ line: i + 1, words: trimmed.split(/\s+/) })
  }
  return lines
}

/**
 * Parse the build graph described on standard input into the structures the
 * scheduling algorithms need: each task's cost, and its dependencies and
 * dependents sorted ascending by name. Throws a `CliError` with exit code 2
 * for any syntax problem or reference to an undeclared task.
 */
export function parseGraph(text) {
  const costs = new Map()
  const declaredAt = new Map()
  // Every name a `dep` line uses, in the order the file uses it, for the
  // "unknown task" check that runs once parsing is otherwise complete.
  const nameUses = []
  // main task name -> set of unique dependency names, in first-seen order.
  const depSets = new Map()

  for (const { line, words } of tokenizeLines(text)) {
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw new CliError(`error: line ${line}: expected task <name> <cost>`, 2)
      const [, name, costText] = words
      if (!NAME_RE.test(name)) throw new CliError(`error: line ${line}: invalid task name ${name}`, 2)
      if (!COST_RE.test(costText)) throw new CliError(`error: line ${line}: cost must be a non-negative integer`, 2)
      if (declaredAt.has(name)) throw new CliError(`error: line ${line}: task ${name} is declared twice`, 2)
      declaredAt.set(name, line)
      costs.set(name, BigInt(costText))
    } else if (directive === 'dep') {
      if (words.length < 3) throw new CliError(`error: line ${line}: expected dep <name> <dependency>...`, 2)
      const [, name, ...deps] = words
      nameUses.push(name)
      let set = depSets.get(name)
      if (!set) {
        set = new Set()
        depSets.set(name, set)
      }
      for (const dep of deps) {
        nameUses.push(dep)
        set.add(dep)
      }
    } else {
      throw new CliError(`error: line ${line}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of nameUses) {
    if (!costs.has(name)) throw new CliError(`error: unknown task ${name}`, 2)
  }

  const names = [...costs.keys()].sort()
  const adj = new Map()
  const reverseAdj = new Map()
  for (const name of names) {
    adj.set(name, [])
    reverseAdj.set(name, [])
  }
  for (const [name, set] of depSets) {
    const deps = [...set].sort()
    adj.set(name, deps)
    for (const dep of deps) reverseAdj.get(dep).push(name)
  }
  for (const name of names) reverseAdj.get(name).sort()

  return { names, costs, adj, reverseAdj }
}
"}

