{"file_path":"./src/schedule.js","content":"import { CliError } from './errors.js'

/**
 * Find the first cycle a depth-first search finds when it starts from each
 * task in ascending name order and walks each task's dependencies in
 * ascending name order. Returns the cycle as an array of names running from
 * the re-entered task back to itself, or `null` when the graph is acyclic.
 */
function findCycle(names, adj) {
  const state = new Map() // absent = unvisited, 1 = on the stack, 2 = done
  for (const start of names) {
    if (state.get(start) === 2) continue
    const stack = [{ name: start, i: 0 }]
    state.set(start, 1)
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const neighbors = adj.get(frame.name)
      if (frame.i < neighbors.length) {
        const next = neighbors[frame.i++]
        const s = state.get(next)
        if (s === 1) {
          const idx = stack.findIndex((f) => f.name === next)
          const cycle = stack.slice(idx).map((f) => f.name)
          cycle.push(next)
          return cycle
        } else if (s !== 2) {
          state.set(next, 1)
          stack.push({ name: next, i: 0 })
        }
      } else {
        state.set(frame.name, 2)
        stack.pop()
      }
    }
  }
  return null
}

/**
 * Walk a DAG bottom-up (children before parents) with an explicit stack, so
 * arbitrarily deep chains cannot overflow the call stack. `combine` folds a
 * node's own value with its already-computed neighbor values.
 */
function foldBottomUp(names, adj, combine) {
  const value = new Map()
  for (const start of names) {
    if (value.has(start)) continue
    const stack = [{ name: start, i: 0 }]
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const neighbors = adj.get(frame.name)
      if (frame.i < neighbors.length) {
        const next = neighbors[frame.i++]
        if (!value.has(next)) stack.push({ name: next, i: 0 })
      } else {
        value.set(frame.name, combine(frame.name, neighbors, value))
        stack.pop()
      }
    }
  }
  return value
}

/**
 * Verify the graph is acyclic, raising the exit-3 cycle error described in
 * the specification when it is not.
 */
export function checkAcyclic({ names, adj }) {
  const cycle = findCycle(names, adj)
  if (cycle) throw new CliError(`error: cycle: ${cycle.join(' -> ')}`, 3)
}

/**
 * Compute each task's wave (depth), start and finish, plus the overall
 * makespan with unlimited workers.
 */
export function computeTimes({ names, costs, adj }) {
  const depth = foldBottomUp(names, adj, (_name, deps) => {
    let d = 0
    for (const dep of deps) d = Math.max(d, depth_get(depth, dep) + 1)
    return d
  })
  // foldBottomUp above needs `depth` while it is still being built; rebuild
  // depth and finish together instead, each as its own bottom-up fold.
  return null
}

function depth_get() {
  throw new Error('unused')
}
"}

