/**
 * Compute each task's wave (its depth in the dependency DAG), start and
 * finish time, plus the overall makespan with unlimited workers.
 */
export function computeTimes({ names, costs, adj }) {
  const depth = foldBottomUp(names, adj, (_name, deps, value) => {
    let d = 0
    for (const dep of deps) d = Math.max(d, value.get(dep) + 1)
    return d
  })
  const finish = foldBottomUp(names, adj, (name, deps, value) => {
    let start = 0n
    for (const dep of deps) if (value.get(dep) > start) start = value.get(dep)
    return start + costs.get(name)
  })
  const start = new Map()
  for (const name of names) start.set(name, finish.get(name) - costs.get(name))

  let makespan = 0n
  for (const f of finish.values()) if (f > makespan) makespan = f

  return { depth, start, finish, makespan }
}

/**
 * Each task's priority for `pack`: the cost of the longest chain of costs
 * running from that task forward to a task nothing depends on.
 */
