  return foldBottomUp(names, reverseAdj, (name, dependents, value) => {
    let best = 0n
    for (const dependent of dependents) if (value.get(dependent) > best) best = value.get(dependent)
    return costs.get(name) + best
  })
}

/**
 * Simulate the graph on a fixed number of workers, greedily starting the
 * highest-priority ready task on the lowest-indexed free worker whenever
 * both are available, as described in the specification.
 */
export function pack(graph, workerCount) {
  const { names, costs, adj } = graph
  const priority = computePriorities(graph)

