  const logs = Array.from({ length: workerCount }, () => [])
  const finishOf = new Map()
  const remaining = new Set(names)
  let time = 0n

  const isReady = (name) => {
    for (const dep of adj.get(name)) {
      const f = finishOf.get(dep)
      if (f === undefined || f > time) return false
    }
    return true
  }

  while (remaining.size > 0) {
    for (;;) {
      let worker = -1
      for (let i = 0; i < workerCount; i++) {
        if (freeAt[i] <= time) {
          worker = i
          break
        }
      }
      if (worker === -1) break

      let best = null
      for (const name of remaining) {
        if (!isReady(name)) continue
        if (best === null || priority.get(name) > priority.get(best) || (priority.get(name) === priority.get(best) && name < best)) {
          best = name
        }
      }
      if (best === null) break

      const taskStart = time
      const taskFinish = taskStart + costs.get(best)
      logs[worker].push({ name: best, start: taskStart, finish: taskFinish })
      freeAt[worker] = taskFinish
      finishOf.set(best, taskFinish)
      remaining.delete(best)
    }

    if (remaining.size === 0) break
    let next = null
    for (const f of freeAt) if (f > time && (next === null || f < next)) next = f
    if (next === null) {
      // A valid, acyclic graph always has a ready task once every worker is
      // idle; this only guards against a defect in the simulation above.
      throw new Error('pack simulation stalled with tasks remaining')
    }
    time = next
  }

  let makespan = 0n
  for (const f of finishOf.values()) if (f > makespan) makespan = f

  return { logs, makespan }
