 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { checkAcyclic, computeTimes, pack } from './schedule.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKER_COUNT_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKER_COUNT_RE.test(argv[1])) throw new CliError('error: workers must be a positive integer', 2)
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw new CliError(USAGE, 2)
}

function renderWaves(graph) {
  const { depth, makespan } = computeTimes(graph)
  const waves = []
  for (const name of graph.names) {
    const d = depth.get(name)
    if (!waves[d]) waves[d] = []
    waves[d].push(name)
  }

  const lines = []
  for (let k = 0; k < waves.length; k++) lines.push(`wave ${k}: ${waves[k].join(' ')}`)
  lines.push(`total ${makespan}`)
  return lines.join('\n') + '\n'
}

function renderExplain(graph) {
  const { depth, start, finish, makespan } = computeTimes(graph)
  const lines = []
  for (const name of graph.names) {
    lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  }
  lines.push(`total ${makespan}`)
  return lines.join('\n') + '\n'
}

function renderPack(graph, workers) {
  const { logs, makespan } = pack(graph, workers)
  const lines = logs.map((log, i) => {
    const entries = log.map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
    return `worker ${i}:${entries}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const graph = parseGraph(input)
  checkAcyclic(graph)

  if (mode === 'waves') process.stdout.write(renderWaves(graph))
  else if (mode === 'explain') process.stdout.write(renderExplain(graph))
  else process.stdout.write(renderPack(graph, workers))
}

try {
  main()
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(err.message + '\n')
    process.exit(err.code)
  }
  throw err
}
